INSERT INTO `items` (`id`,`owner_id`,`category_id`,`name`,`slug`,`description`,`specifications`,`terms_conditions`,`price_daily`,`price_weekly`,`price_monthly`,`status`,`created_at`) VALUES
(4, 5, 1, 'Sony A7III + Lensa 28-70mm', 'sony-a7iii-lensa-28-70mm-4', 'Kamera dan lensa profesional siap pakai untuk foto maupun video. Termasuk aksesoris pendukung, baterai ekstra, dan kartu memori. Cocok untuk acara, konten kreator, maupun dokumentasi.', 'Sensor full-frame 24MP; ISO 100-51200; 5-axis stabilizer; baterai NP-FZ100; 2x SD card slot; berat 650g.', 'Sewa minimal 1 hari. Wajib menyerahkan KTP. Barang dikembalikan dalam kondisi sama. Kerusakan ditanggung penyewa.', 45000, 292000, 1125000, 'active', '2026-07-14 04:45:12'),
(5, 15, 2, 'Tenda Dome 4 Orang Eiger', 'tenda-dome-4-orang-eiger-5', 'Peralatan camping berkualitas untuk petualangan alam terbuka. Ringan, kokoh, dan mudah dibawa. Termasuk tenda, sleeping bag, dan perlengkapan survival.', 'Kapasitas 4 orang; bahan polyester waterproof 3000mm; berat 3.2kg; mudah dipasang <10 menit; dilengkapi jendela ventilasi.', 'Sewa minimal 1 hari. Wajib menyerahkan KTP. Barang dikembalikan dalam kondisi sama. Kerusakan ditanggung penyewa.', 150000, 975000, 3750000, 'active', '2026-07-14 04:25:12'),
(6, 8, 3, 'Honda Beat 2022', 'honda-beat-2022-6', 'Kendaraan terawat dengan dokumen lengkap dan asuransi dasar. Pas untuk perjalanan wisata maupun kebutuhan harian. Sudah termasuk helm dan perlengkapan keselamatan.', 'Transmisi otomatis; bahan bakar efisien; kapasitas 4 penumpang; AC dual zone; sudah service rutin; odometer terawat.', 'Sewa minimal 1 hari. Wajib menyerahkan KTP. Barang dikembalikan dalam kondisi sama. Kerusakan ditanggung penyewa.', 35000, 228000, 875000, 'active', '2026-07-10 08:27:12'),
